        public List<User> GetAllUsers()
        {
            List<User> users = new List<User>();

            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                connection.Open();

                string query = "SELECT * FROM Users";
                SqlCommand sqlCommand = new SqlCommand(query, connection);
                SqlDataReader reader = sqlCommand.ExecuteReader(); // ใช้ SqlDataReader แทน ExecuteScalar

                while (reader.Read())
                {
                    // ดึงข้อมูลจาก SqlDataReader
                    int userId = Convert.ToInt32(reader["UserId"]);
                    string userName = reader["UserName"].ToString();
                    string email = reader["Email"].ToString();
                    string role = reader["Role"].ToString();

                    // สร้าง object สำหรับข้อมูลผู้ใช้
                    User user = new User
                    {
                        UserId = userId,
                        UserName = userName,
                        Email = email,
                        Role = role
                    };

                    users.Add(user); // เพิ่มข้อมูลผู้ใช้ลงใน list
                }

                reader.Close(); // ปิด SqlDataReader
            }

            return users; // คืนค่า list ของผู้ใช้ทั้งหมด
